{
 "command": "for f in Makefile pyproject.toml docker-compose.yml docs/testing.md docs/dev-setup.md services/notifier/pyproject.toml .gitignore .engramdb/memories/rerunning-ci-builds*.md .engramdb/memories/release-*.md .engramdb/memories/run-tests-with-make-test-fast*.md .engramdb/memories/running-the-notifier-s-tests*.md; do echo \"=== $f\"; cat \"$f\"; done; grep -rniE \"ci\\b|jenkins|buildkite|circle|pipeline\" README.md docs --include=*.md | head -30"
}

{
 "command": "cat docs/runbook.md; head -30 scripts/gen_fx_fixtures.py; ls tests tests/fixtures 2>/dev/null; grep -rnE \"environ|getenv\" src tests scripts services --include=*.py | head -30; cat .engramdb/memories/where-fx-rates-come-from-current*.md | sed -n 10,20p"
}

{
 "command": "git ls-files tests | head -20; grep -n \"fixtures\\|fxdata\\|FX_DIR\" tests/*.py | head; grep -rn \"psycopg\\|pytest.mark\\|LEDGER_SANDBOX\" tests scripts/ledger_smoke.py | head"
}
